// generates `Generated/` (Rust core as an XCFramework + UniFFI Swift bindings).
import PackageDescription

let package = Package(
    name: "Navori",
    platforms: [.macOS(.v15)],
    products: [
        .executable(name: "Navori", targets: ["Navori"]),
    ],
    targets: [
        .binaryTarget(
            name: "NavoriCoreFFI",
            path: "Generated/NavoriCoreFFI.xcframework"
        ),
        // Generated by UniFFI. Swift 5 mode: generated async code is not fully Sendable yet
        // (uniffi-rs #2448). Only `CoreStore` touches this module.
        .target(
            name: "NavoriCore",
            dependencies: ["NavoriCoreFFI"],
            path: "Generated/NavoriCore",
            swiftSettings: [.swiftLanguageMode(.v5)]
        ),
        .executableTarget(
            name: "Navori",
            dependencies: ["NavoriCore"],
            path: "Navori",
            swiftSettings: [.swiftLanguageMode(.v6)]
        ),
    ]
)
